/**
 * A captured rules version 1 operation table for replay validation only: four top-level sends
 * (`team/message-sent`) and the two `team/thread-replied` operations the version 1 invitation
 * flow committed in one Project, written by the build that still committed them. It is not
 * regenerated at runtime. To extend it, boot an `AgentTeamLedger` with `{ rulesVersion: 1 }` over
 * a clone of these records, replay the writes with fixed `occurredAt` (and ideally `operationId`
 * and `ref`) hooks, then paste the pool's stored `operations` entries — not the re-encoded table
 * values, which replay fills with schema defaults — back as JSON. The ledger carries no rules marker.
 */
export interface RulesV1Ledger {
  readonly records: Array<[string, unknown]>
  readonly projectRef: string
  readonly members: Readonly<Record<'alice' | 'bob' | 'carol' | 'dave', string>>
  /** Human Task, no mentions, plus the invitation and undelivered replies below. */
  readonly task: { readonly threadRef: string; readonly taskRef: string; readonly revision: number }
  /** Human reply that invited carol; the recorded Attention starts at this reply. */
  readonly invitation: { readonly messageRef: string; readonly sequence: number; readonly revision: number }
  /** alice's reply that mentioned dave; dave was outside the Project, so it recorded no mention. */
  readonly undelivered: { readonly messageRef: string; readonly sequence: number; readonly revision: number }
  /** alice's discussion with bob as an explicit recipient. */
  readonly discussion: { readonly threadRef: string; readonly revision: number }
  /** Human discussion that says `@all`; the stored mentions are alice, bob and carol. */
  readonly standup: { readonly threadRef: string; readonly revision: number }
  /** Human Task that mentions dave, who is outside the Project. */
  readonly outsider: { readonly threadRef: string; readonly taskRef: string; readonly revision: number }
}

